// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 amt1, uint256 amt2) internal {
        amt1 = bound(amt1, 0, 1000000000000000000000000000000);
        amt2 = bound(amt2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amt1 == 10 && amt2 == 10);
        vm.assume(address(this).balance >= amt1 + amt2);
        vm.assume(uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2 != 0);
        try c.play{value: amt1}() {} catch { return; }
        try c.play{value: amt2}() {} catch { return; }
        assertTrue(c.pot() == amt1 + amt2);
    }

    function testFuzz_test(uint256 amt1, uint256 amt2) public {
        _test(amt1, amt2);
    }

    receive() external payable {}
}
